import unittest

from wrap import wrap


class Rules(unittest.TestCase):
    def test_paragraphs(self):
        for text, expected in [("", [""]), ("\na\n \t\nb\n", ["", "a", "", "b", ""])]:
            self.assertEqual(wrap(text, 4, ">"), expected)

    def test_whitespace(self):
        self.assertEqual(wrap(" \ta\u2003b\r\vc  ", 8), ["a b c"])

    def test_greedy_exact_fit(self):
        self.assertEqual(wrap("aa b c dd e", 4), ["aa b", "c dd", "e"])

    def test_indent_resets(self):
        self.assertEqual(wrap("abcd e f\ng hi j", 4, ".."), ["abcd", "..e", "..f", "g hi", "..j"])

    def test_long_words(self):
        self.assertEqual(wrap("abcdefghij k", 4, ">"), ["abcd", ">efg", ">hij", ">k"])
        self.assertEqual(wrap("a abcdef z", 5, ">"), ["a", ">abcd", ">ef z"])
        self.assertEqual(wrap("ab cd", 1), ["a", "b", "c", "d"])

    def test_arguments(self):
        for width, indent in [(0, ""), (-1, ""), (2.5, ""), ("3", ""), (3, "..."), (1, "..")]:
            with self.assertRaises(ValueError):
                wrap("", width, indent)

